package gg.aetherfall.core.module;
import gg.aetherfall.core.AetherCore; import gg.aetherfall.core.util.Text; import org.bukkit.block.Block; import org.bukkit.block.data.Ageable; import org.bukkit.entity.Player; import org.bukkit.event.EventHandler; import org.bukkit.event.Listener; import org.bukkit.event.block.BlockBreakEvent; import java.util.concurrent.ThreadLocalRandom;
public final class CropMutations implements Listener { private final AetherCore plugin; public CropMutations(AetherCore p){plugin=p;} @EventHandler public void harvest(BlockBreakEvent e){Block b=e.getBlock();if(!(b.getBlockData() instanceof Ageable a)||a.getAge()!=a.getMaximumAge())return;Player p=e.getPlayer();if(ThreadLocalRandom.current().nextInt(100)<plugin.getConfig().getInt("farming.mutation-chance",3)){String item=switch(b.getType()){case WHEAT->"golden_seed";case CARROTS->"golden_seed";default->"ancient_bark";};plugin.items().give(p,item,1);p.sendMessage(Text.mm("<gold>Crop mutation discovered:</gold> <yellow>"+plugin.items().displayName(item)));}}}
